mapper.select:
SELECT gather_id, gather_name, gather_type, book_id, book_name, org_id, org_name, period, status, submit_time, approve_time, create_by, create_time, update_by, update_time FROM finance_gather
AND gather_name LIKE '%' || #{params.gatherName} || '%'
AND gather_type = #{params.gatherType}
AND book_id = #{params.bookId}
AND org_id = #{params.orgId}
AND period = #{params.period}
AND status = #{params.status}
ORDER BY create_time DESC

SELECT COUNT(*) as total_count, SUM(CASE WHEN status = 'DRAFT' THEN 1 ELSE 0 END) as draft_count, SUM(CASE WHEN status = 'SUBMITTED' THEN 1 ELSE 0 END) as submitted_count, SUM(CASE WHEN status = 'APPROVED' THEN 1 ELSE 0 END) as approved_count, SUM(CASE WHEN status = 'REJECTED' THEN 1 ELSE 0 END) as rejected_count FROM finance_gather
AND period = #{params.period}
AND org_id = #{params.orgId}
